check!(canvas_resize_and_put, "<canvas id=c></canvas>", "const c=document.getElementById('c'); const x=c.getContext('2d'); x.fillRect(0,0,10,10); c.width=5; c.height=5; console.log(x.getImageData(0,0,1,1).data[3]); const img=x.createImageData(2,2); img.data.fill(200); x.putImageData(img, 1, 1); console.log(x.getImageData(1,1,1,1).data.join(), x.getImageData(0,0,1,1).data.join(), img instanceof ImageData); const p=new Path2D(); p.rect(0,0,5,5); x.fill(p); console.log(x.getImageData(4,4,1,1).data[3]);", "0\n200,200,200,200 0,0,0,0 true\n255");
check!(canvas_draw_other_canvas, "<canvas id=a width=2 height=2></canvas><canvas id=b width=2 height=2></canvas>", "const a=document.getElementById('a'), b=document.getElementById('b'); a.getContext('2d').fillStyle='green'; a.getContext('2d').fillRect(0,0,2,2); b.getContext('2d').drawImage(a, 0, 0); console.log(Array.from(b.getContext('2d').getImageData(1,1,1,1).data).join()); b.getContext('2d').drawImage(new Image(), 0, 0);", "0,128,0,255");
check!(element_click_method, "<input id=c type=checkbox><a id=a href='https://go.test/'>x</a><button id=b>b</button>", "const c=document.getElementById('c'); let n=0; c.addEventListener('click', e=>{ n++; console.log('click', c.checked, e.isTrusted, e instanceof MouseEvent, e.bubbles); }); c.addEventListener('change', ()=>console.log('change', c.checked)); c.click(); c.addEventListener('click', e=>e.preventDefault()); c.click(); console.log(c.checked, n); document.getElementById('b').onclick=function(e){ console.log('btn', this.id, e.target===this); }; document.getElementById('b').click(); document.getElementById('a').click();", "click true false true true\nchange true\nclick false false true true\ntrue 2\nbtn b true");
check!(focus_blur_methods, "<input id=a><input id=b><div id=d></div><div id=t tabindex=0></div>", "const a=document.getElementById('a'), b=document.getElementById('b'); const log=[]; for (const el of [a,b]) for (const t of ['focus','blur','focusin','focusout']) el.addEventListener(t, e=>log.push(el.id+':'+t+(e.relatedTarget?'>'+e.relatedTarget.id:''))); a.focus(); console.log(document.activeElement===a, a.matches(':focus'), log.join()); b.focus(); console.log(document.activeElement.id, log.slice(2).join()); b.blur(); console.log(document.activeElement===document.body, log.slice(6).join()); document.getElementById('d').focus(); console.log(document.activeElement===document.body); document.getElementById('t').focus(); console.log(document.activeElement.id);", "true true a:focus,a:focusin\nb a:blur>b,a:focusout>b,b:focus>a,b:focusin>a\ntrue b:blur,b:focusout\ntrue\nt");
check!(custom_elements_lifecycle, "<x-a id=first></x-a>", "class XA extends HTMLElement { static get observedAttributes() { return ['p']; } constructor() { super(); console.log('ctor', this.tagName, this.isConnected); } connectedCallback() { console.log('connected', this.id); } disconnectedCallback() { console.log('disconnected', this.id); } attributeChangedCallback(n,o,v) { console.log('attr', n, o, v); } } customElements.whenDefined('x-a').then(c=>console.log('defined', c===XA)); customElements.define('x-a', XA); console.log(document.getElementById('first') instanceof XA, customElements.get('x-a')===XA, customElements.getName(XA)); const e=new XA(); e.id='second'; e.setAttribute('p','1'); document.body.appendChild(e); e.setAttribute('p','2'); e.remove(); const f=document.createElement('x-a'); f.id='third'; console.log(f instanceof XA); document.body.innerHTML+='<x-a id=fourth p=q></x-a>'; try { customElements.define('x-a', class extends HTMLElement{}) } catch(err) { console.log(err.name) } try { customElements.define('bad', XA) } catch(err) { console.log(err.name) }", "ctor X-A true\nconnected first\ntrue true x-a\nctor X-A false\nattr p null 1\nconnected second\nattr p 1 2\ndisconnected second\nctor X-A false\ntrue\ndisconnected first\nctor X-A true\nconnected first\nctor X-A true\nattr p null q\nconnected fourth\nNotSupportedError\nSyntaxError\ndefined true");
check!(custom_element_extends_builtin, "", "class FB extends HTMLButtonElement { constructor() { super(); this.textContent='fancy'; } } customElements.define('fancy-button', FB, { extends: 'button' }); const b=new FB(); console.log(b.tagName, b.getAttribute('is'), b.textContent, b instanceof HTMLButtonElement, b instanceof FB); const c=document.createElement('button', { is: 'fancy-button' }); console.log(c instanceof FB, c.textContent);", "BUTTON fancy-button fancy true true\ntrue fancy");
check!(element_internals_and_animate, "<div id=d></div>", "const d=document.getElementById('d'); const a=d.animate([{opacity:0},{opacity:1}], 300); console.log(a.playState, a instanceof Animation, d.getAnimations().length); a.finished.then(()=>console.log('finished')); d.requestFullscreen().catch(e=>console.log('fs rejected')); console.log(d.checkVisibility());", "finished true 0\ntrue\nfinished\nfs rejected");
